using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using Newtonsoft.Json;
public static class F1Inspect {
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));
 static float[] V(Vector3 p)=>new[]{p.x,p.y,p.z};
 static string P(Transform t)=>t.parent?P(t.parent)+"/"+t.name:t.name;
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying)throw new Exception("Saved edit mode required; preserve pending user edits");string h=R+"/SourceAssets/F1_FullFloor/";if(File.Exists(h+"before.json"))throw new Exception("Baseline already exists");
 var inventory=AssetDatabase.FindAssets("t:Model",new[]{"Assets/Afrer_Seconds/05.Model/Props/B1","Assets/Afrer_Seconds/05.Model/Props/1F","Assets/Afrer_Seconds/05.Model/Props/B2","Assets/Afrer_Seconds/05.Model/Environment/1F"}).Select(AssetDatabase.GUIDToAssetPath).Select(p=>{var g=AssetDatabase.LoadAssetAtPath<GameObject>(p);var rs=g.GetComponentsInChildren<Renderer>();Bounds b=new Bounds();bool first=true;foreach(var x in rs.Where(x=>!x.name.Contains("LOD1")&&!x.name.Contains("LOD2"))){if(first){b=x.bounds;first=false;}else b.Encapsulate(x.bounds);}return new{asset=p,center=V(b.center),size=V(b.size),materials=rs.SelectMany(x=>x.sharedMaterials).Where(x=>x).Select(AssetDatabase.GetAssetPath).Distinct().ToArray(),meshes=g.GetComponentsInChildren<MeshFilter>().Select(f=>new{f.name,triangles=f.sharedMesh.triangles.Length/3}).ToArray()};}).ToArray();
 var result=new{scene=s.path,saved=!s.isDirty,roots=s.GetRootGameObjects().Select(g=>new{g.name,position=V(g.transform.position)}).ToArray(),markers=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).Where(t=>t.name.Contains("Arrival")||t.name.Contains("Transition")||t.name.Contains("Landing")||t.name.Contains("Cabin")).Select(t=>new{path=P(t),position=V(t.position),rotation=V(t.eulerAngles)}).ToArray(),player=s.GetRootGameObjects().Where(g=>g.name.StartsWith("Player")).Select(g=>new{g.name,position=V(g.transform.position),rotation=V(g.transform.eulerAngles)}).ToArray(),inventory};File.WriteAllText(h+"before.json",JsonConvert.SerializeObject(result,Formatting.Indented));return new{result.scene,result.saved,models=inventory.Length,markers=result.markers};}
}
